@@ -0,0 +1,68 @@
+name: Integration (real Postgres)
+
+# Runs tests/integration against a throwaway pgvector database. These suites skip themselves when
+# Postgres is unreachable, so scripts/check-integration-report.ts fails the job on an empty or
+# skipped run. A separate workflow (not in ci.yml) so the two required checks keep their names.
+# No ALLOW_NETWORK: any stray live model call fails loudly instead of spending money.
+on:
+  pull_request:
+    paths:
+      - "src/**"
+      - "tests/integration/**"
+      - "tests/setup.ts"
+      - "drizzle/**"
+      - "scripts/setup-db.ts"
+      - "scripts/check-integration-report.ts"
+      - "vitest.integration.config.ts"
+      - "package.json"
+      - "pnpm-lock.yaml"
+      - ".github/workflows/integration.yml"
+  push:
+    branches: [main, beta]
+  workflow_dispatch:
+
+concurrency:
+  group: integration-${{ github.ref }}
+  cancel-in-progress: true
+
+permissions:
+  contents: read
+
+jobs:
+  integration:
+    name: Integration tests (pgvector)
+    runs-on: ubuntu-latest
+    timeout-minutes: 15
+    services:
+      postgres:
+        image: pgvector/pgvector:pg16
+        env:
+          POSTGRES_USER: test
+          POSTGRES_PASSWORD: test # throwaway CI database, not a secret
+          POSTGRES_DB: founderos_test
+        ports:
+          - 5432:5432
+        options: >-
+          --health-cmd "pg_isready -U test -d founderos_test"
+          --health-interval 5s
+          --health-timeout 5s
+          --health-retries 12
+    env:
+      DATABASE_URL: postgresql://test:test@localhost:5432/founderos_test
+      # config.ts validates these on import; the values are never sent anywhere.
+      TELEGRAM_BOT_TOKEN: ci-placeholder
+      TELEGRAM_CHAT_ID: "0"
+    steps:
+      - uses: actions/checkout@v4
+      - uses: pnpm/action-setup@v4
+        with:
+          version: 10
+      - uses: actions/setup-node@v4
+        with:
+          node-version: "22"
+          cache: "pnpm"
+      - run: pnpm install --frozen-lockfile
+      - name: Apply migrations
+        run: node --import tsx/esm scripts/setup-db.ts
+      - name: Run integration suites
+        run: pnpm test:integration:ci
diff --git a/scripts/check-integration-report.ts b/scripts/check-integration-report.ts
new file mode 100644
index 00000000..a1e8cf80
--- /dev/null
+++ b/scripts/check-integration-report.ts
@@ -0,0 +1,62 @@
+/**
+ * CI guard for the real-database integration suites (tests/integration).
+ *
+ * Every DB suite there skips itself when DATABASE_URL is unreachable, and vitest exits 0 on an
+ * all-skipped run, so a broken service container would look green. This reads vitest's JSON report
+ * and fails on: no tests, a failed test, a skipped/todo test, or a file that did not pass.
+ *
+ * Usage: node --import tsx/esm scripts/check-integration-report.ts <report.json>
+ */
+
+import { readFileSync } from "node:fs";
+import { pathToFileURL } from "node:url";
+
+export interface VitestJsonReport {
+  numTotalTests?: number;
+  numPassedTests?: number;
+  numFailedTests?: number;
+  numPendingTests?: number;
+  numTodoTests?: number;
+  testResults?: Array<{ name?: string; status?: string }>;
+}
+
+export interface ReportVerdict {
+  ok: boolean;
+  problems: string[];
+}
+
+export function checkIntegrationReport(report: VitestJsonReport): ReportVerdict {
+  const problems: string[] = [];
+  const passed = report.numPassedTests ?? 0;
+  const failed = report.numFailedTests ?? 0;
+  const skipped = (report.numPendingTests ?? 0) + (report.numTodoTests ?? 0);
+
+  if (passed === 0) problems.push("no integration test passed: the run was empty or all skipped");
+  if (failed > 0) problems.push(`${failed} integration test(s) failed`);
+  if (skipped > 0) {
+    problems.push(`${skipped} integration test(s) skipped or todo: the database was probably unreachable`);
+  }
+  for (const file of report.testResults ?? []) {
+    if (file.status !== "passed") problems.push(`${file.name ?? "unknown file"}: status ${file.status ?? "missing"}`);
+  }
+  return { ok: problems.length === 0, problems };
+}
+
+function main(path: string | undefined): number {
+  if (!path) {
+    console.error("usage: check-integration-report.ts <vitest-json-report>");
+    return 2;
+  }
+  const report = JSON.parse(readFileSync(path, "utf8")) as VitestJsonReport;
+  const verdict = checkIntegrationReport(report);
+  if (!verdict.ok) {
+    for (const p of verdict.problems) console.error(`❌ ${p}`);
+    return 1;
+  }
+  console.log(`✅ integration: ${report.numPassedTests} passed, 0 skipped, 0 failed`);
+  return 0;
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  process.exit(main(process.argv[2]));
+}
diff --git a/tests/unit/scripts/check-integration-report.test.ts b/tests/unit/scripts/check-integration-report.test.ts
new file mode 100644
index 00000000..5d608938
--- /dev/null
+++ b/tests/unit/scripts/check-integration-report.test.ts
@@ -0,0 +1,50 @@
+/**
+ * The integration-suite guard must never let an empty or skipped run look green, and the workflow
+ * that runs it must stay fail-loud with the network kill-switch on.
+ */
+
+import { readFileSync } from "node:fs";
+import { describe, it, expect } from "vitest";
+import { checkIntegrationReport } from "../../../scripts/check-integration-report.js";
+
+const green = {
+  numTotalTests: 3,
+  numPassedTests: 3,
+  numFailedTests: 0,
+  numPendingTests: 0,
+  numTodoTests: 0,
+  testResults: [{ name: "a.test.ts", status: "passed" }],
+};
+
+describe("checkIntegrationReport", () => {
+  it("passes when every test ran and passed", () => {
+    expect(checkIntegrationReport(green)).toEqual({ ok: true, problems: [] });
+  });
+
+  it("fails an empty run", () => {
+    const v = checkIntegrationReport({ ...green, numTotalTests: 0, numPassedTests: 0, testResults: [] });
+    expect(v.ok).toBe(false);
+    expect(v.problems.join(" ")).toMatch(/empty or all skipped/);
+  });
+
+  it("fails a run where the DB suites skipped themselves", () => {
+    const v = checkIntegrationReport({ ...green, numPendingTests: 12 });
+    expect(v.ok).toBe(false);
+    expect(v.problems.join(" ")).toMatch(/12 integration test\(s\) skipped/);
+  });
+
+  it("fails on a failed test and a failed file", () => {
+    const v = checkIntegrationReport({
+      ...green,
+      numFailedTests: 1,
+      testResults: [{ name: "b.test.ts", status: "failed" }],
+    });
+    expect(v.ok).toBe(false);
+    expect(v.problems).toContain("1 integration test(s) failed");
+    expect(v.problems).toContain("b.test.ts: status failed");
+  });
+
+  it("treats a missing report body as an empty run", () => {
+    expect(checkIntegrationReport({}).ok).toBe(false);
+  });
+});
